.source-feature-layer .bottle-pass{
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
}
.source-feature-layer .bottle-pass__x_popup{
  max-height: 90%;
}
.source-feature-layer .bottle-pass__x_popup__header{
  background-color: var(--source-feature-color-0);
  border-top-left-radius: 17px;
  flex: none;
  flex-direction: column;
  padding: 0;
  color: var(--source-feature-color-1);
  font-weight: normal;
  overflow: visible;
}
.source-feature-layer .bottle-pass__x_popup__title{
  flex: none;
  color: var(--source-feature-color-1);
  margin: 10px 0 15px 0;
  font-weight: bold;
}
.source-feature-layer .bottle-pass__x_popup__content{
  position: relative;
  border-radius: 0 0 17px 17px;
  overflow-x: hidden;
}
.source-feature-layer .bottle-pass__manual{
  background-size: 11px 15px;
  height: 15px;
  width: 11px;
  position: absolute;
  left: 14px;
  top: 10px;
  cursor: pointer;
}
.source-feature-layer .bottle-pass__x_popup__close-icon{
  background-size: 16px 16px;
  height: 16px;
  width: 16px;
}
.source-feature-layer .bottle-pass__header-border-btm{
  background-color: var(--source-feature-color-2);
  height: 1px;
  width: 100%;
  margin-bottom: -1px;
  z-index: 2;
}
.source-feature-layer .bottle-pass__header-info{
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 0 15px;
}
.source-feature-layer .bottle-pass__controls{
  display: flex;
  margin: 0 0 10px 0;
}
.source-feature-layer .bottle-pass__control{
  display: flex;
  align-items: center;
  border-radius: 6px;
  width: 122px;
  height: 36px;
  font-size: 10px;
  margin-right: 15px;
}
.source-feature-layer .bottle-pass__control:last-child,.source-feature-layer .bottle-pass__control:only-child{
  margin-right: 0;
}
.source-feature-layer .bottle-pass__control--premium{
  background-image: linear-gradient(to bottom, var(--source-feature-color-3) -1%, var(--source-feature-color-4) 101%);
  transition: box-shadow 500ms linear;
  cursor: pointer;
}
.source-feature-layer .bottle-pass__control--premium:active{
  box-shadow: inset 0 0 12px 0 var(--source-feature-color-5);
}
.source-feature-layer .bottle-pass__control--state{
  background-color: var(--source-feature-color-6);
}
.source-feature-layer .bottle-pass__premium-icon-bg{
  background-size: 42px 36px;
  height: 36px;
  width: 42px;
  display: flex;
  align-items: center;
  flex-shrink: 0;
  position: relative;
}
.source-feature-layer .bottle-pass__premium-icon{
  background-size: 24px 24px;
  height: 24px;
  width: 24px;
  margin-left: 5px;
}
.source-feature-layer .bottle-pass__premium-purchased-icon{
  background-size: 12px 12px;
  height: 12px;
  width: 12px;
  position: absolute;
  bottom: 6px;
  right: 12px;
}
.source-feature-layer .bottle-pass__premium-btn-title{
  font-weight: bold;
  margin-left: -8px;
  white-space: pre-wrap;
  cursor: pointer;
}
.source-feature-layer .bottle-pass__season-state-icon{
  flex-shrink: 0;
}
.source-feature-layer .bottle-pass__season-state-icon--timer{
  background-size: 24px 24px;
  height: 24px;
  width: 24px;
  margin: 0 5px;
}
.source-feature-layer .bottle-pass__season-state-icon--finish{
  background-size: 30px 24px;
  height: 24px;
  width: 30px;
  margin: 0 2px;
}
.source-feature-layer .bottle-pass__season-state-info{
  display: flex;
  flex-direction: column;
}
.source-feature-layer .bottle-pass__season-state-timer{
  font-weight: bold;
}
.source-feature-layer .bottle-pass__season-stats{
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0 0 10px 0;
}
.source-feature-layer .bottle-pass__season-stats-blink{
  -webkit-animation: season-stats-blink 1500ms linear;
          animation: season-stats-blink 1500ms linear;
}
.source-feature-layer .bottle-pass__season-stats-icon{
  background-size: 22px 21px;
  height: 21px;
  width: 22px;
}
.source-feature-layer .bottle-pass__season-stats-progress{
  background-color: var(--source-feature-color-7);
  width: 138px;
  height: 16px;
  border-radius: 8px;
  position: relative;
  margin: 0 5px;
  overflow: hidden;
}
.source-feature-layer .bottle-pass__season-stats-progress--bar{
  background-color: var(--source-feature-color-8);
  margin: unset;
